    "toDateDescription": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Повертає перший аргумент, перетворений на дату за рядком формату дати як другий аргумент. Завжди в UTC. Використовуйте `to_date_tz`, щоб вказати часовий пояс." } },
    "dayDescription": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Повертає день місяця як число від 1 до 31 з аргументу." } },
    "dateDiffDescription": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "За одиницею дати для вимірювання як перший аргумент ('year', 'month', 'week', 'day', 'hour', 'minute', 'seconds') обчислює та повертає кількість одиниць від другого аргументу до третього." } },
    "andDescription": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Повертає логічне І першого та другого аргументів, тому якщо обидва true, результат true, інакше false." } },
