    "searchDescription": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Повертає додатне ціле число, починаючи з 1, для першого входження другого аргументу в першому, або 0, якщо входження не знайдено." } },
    "rowIdDescription": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Повертає унікальний ідентифікаційний номер рядка." } },
