    "rightDescription": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Витягує найправіші символи з першого вводу, зупиняється, коли витягнуто кількість символів, вказану другим вводом." } },
    "trimDescription": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Видаляє всі пробіли з лівої та правої сторін вводу." } },
    "regexReplaceDescription": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Замінює будь-який текст у першому вводі, що відповідає регулярному виразу, вказаному другим вводом, текстом третього вводу. Повертає '#ERROR!', якщо шаблон регулярного виразу недійсний." } },
